const API_BASE = "/api";
async function fetchJson(url, options) {
  const headers = {
    ...options?.headers
  };
  if (options?.body) {
    headers["Content-Type"] = "application/json";
  }
  const response = await fetch(`${API_BASE}${url}`, {
    ...options,
    credentials: "include",
    headers
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error || errorData.message || `HTTP ${response.status}`);
  }
  return response.json();
}
export const api = {
  // Health
  getHealth: () => fetchJson("/health"),
  getHealthReady: () => fetchJson("/health/ready"),
  // Locations
  getLocations: () => fetchJson("/locations"),
  getLocation: (id) => fetchJson(`/locations/${id}`),
  // Areas
  getAreas: (locationId) => fetchJson(`/locations/${locationId}/areas`),
  // Gates
  getGates: () => fetchJson("/gates"),
  getGate: (id) => fetchJson(`/gates/${id}`),
  // Commands
  sendCommand: (gateId, action) => fetchJson(`/gates/${gateId}/command`, {
    method: "POST",
    body: JSON.stringify({ action })
  }),
  // Audit logs
  getAuditLogs: (params) => {
    const searchParams = new URLSearchParams();
    if (params?.gateId) searchParams.set("gateId", params.gateId);
    if (params?.limit) searchParams.set("limit", String(params.limit));
    if (params?.offset) searchParams.set("offset", String(params.offset));
    const query = searchParams.toString();
    return fetchJson(`/audit-logs${query ? `?${query}` : ""}`);
  },
  // Config
  getConfig: () => fetchJson("/config"),
  updateConfig: (config) => fetchJson("/config", {
    method: "PUT",
    body: JSON.stringify(config)
  }),
  reloadConfig: () => fetchJson("/config/reload", { method: "POST" }),
  getConfigHistory: () => fetchJson("/config/history"),
  rollbackConfig: (filename) => fetchJson(`/config/rollback/${encodeURIComponent(filename)}`, {
    method: "POST"
  }),
  // Auth
  getCurrentUser: () => fetchJson("/auth/me"),
  login: (returnTo) => {
    const params = returnTo ? `?returnTo=${encodeURIComponent(returnTo)}` : "";
    window.location.href = `${API_BASE}/auth/login${params}`;
  },
  logout: () => fetchJson("/auth/logout", { method: "POST" }),
  // Guest
  getGuestScope: () => fetchJson("/guest/scope"),
  redeemGuestToken: (token) => fetchJson(`/guest/redeem?token=${encodeURIComponent(token)}`),
  createInvite: (data) => fetchJson("/guest/invites", {
    method: "POST",
    body: JSON.stringify(data)
  }),
  getInvites: () => fetchJson("/guest/invites"),
  deleteInvite: (id) => fetchJson(`/guest/invites/${id}`, { method: "DELETE" }),
  // Admin
  getUsers: () => fetchJson("/admin/users"),
  getUser: (id) => fetchJson(`/admin/users/${id}`),
  grantPermission: (userId, data) => fetchJson(`/admin/users/${userId}/permissions`, {
    method: "POST",
    body: JSON.stringify(data)
  }),
  revokePermission: (permissionId) => fetchJson(`/admin/permissions/${permissionId}`, { method: "DELETE" }),
  getScopes: () => fetchJson("/admin/scopes")
};

